#include <queue>
#include <iostream>

int main() {
    std::queue<int> q1;
    std::queue<int> q2;
    q1.push(10); q1.push(20);
    q2.push(10); q2.push(30);

    // Lexicographical comparison: 20 < 30, so q1 < q2
    if (q1 < q2) {
        std::cout << "q1 is lexicographically less than q2." << std::endl;
    }

    std::queue<int> q3;
    q3.push(10); q3.push(20);

    if (q1 == q3) {
        std::cout << "q1 equals q3 (same elements in same order)." << std::endl;
    }
}
